/**
 * Transform stage — enriches validated records with labels and priorities.
 */

function transformRecords(records) {
  return records.map(record => ({
    ...record,
    label: record.valid ? record.name.toUpperCase() : `[REJECTED] ${record.name}`,
    priority: record.valid ? (record.score > 80 ? 'high' : 'normal') : 'none',
    _stage: 'transformed'
  }));
}

module.exports = { transformRecords };
===
/**
 * Output stage — formats transformed records into final JSON.
 */

function formatOutput(records) {
  return records.map(record => ({
    id: record.id,
    name: record.name,
    status: record.valid ? 'valid' : 'invalid',
    label: record.label,
    priority: record.priority,
    score: record.score
  }));
}

module.exports = { formatOutput };
===
/**
 * Pipeline configuration.
 */

module.exports = {
  THRESHOLD: 50,    // Records with score >= THRESHOLD are valid
  VERSION: '2.1.0'
};

